#!/usr/bin/env bash
# Generated by wikiloop build. Edit wikiloop.toml or guides/, not this file.
# One-line entry point for the acme-wiki installer, for a wiki repo that is private:
#
#   curl -fsSL <where you publish this file> | bash
#
# Checks that gh is installed and logged in, then hands over to install.sh from the repo, which
# checks the rest and installs the plugin. Installs nothing itself. Publish it world-readable
# only if nothing in it is internal: it names the repo and nothing else.
set -euo pipefail

REPO="acme/ai-wiki"

if ! command -v gh >/dev/null 2>&1; then
  if [ "$(uname)" = Darwin ]; then
    echo "gh is not installed. Run: brew install gh, then rerun this command." >&2
  else
    echo "gh is not installed. See https://github.com/cli/cli/blob/trunk/docs/install_linux.md, then rerun this command." >&2
  fi
  exit 1
fi

if ! gh auth status >/dev/null 2>&1; then
  echo "gh is not logged in. Run: gh auth login, then rerun this command." >&2
  exit 1
fi

script="$(mktemp)"
trap 'rm -f "$script"' EXIT

if ! gh api "repos/$REPO/contents/install.sh" -H 'Accept: application/vnd.github.raw' >"$script" 2>/dev/null; then
  echo "cannot read $REPO; ask in #platform for access to acme/ai-wiki." >&2
  exit 1
fi

exec bash "$script" "$@"
